<?php
namespace App\Traits;
use App\Models\Order; use App\Models\PaymentTransaction; use App\Support\SensitiveDataRedactor; use Illuminate\Support\Facades\Http;
trait HandlesPaymobPayment {
 public function initiatePaymobPayment(Order $order,?PaymentTransaction $paymentTransaction=null): array { $intention=$this->createPaymobIntention($order);if(empty($intention['success']))return ['success'=>false,'message'=>$intention['message']??'فشل إنشاء عملية الدفع'];$url=$this->buildPaymobUnifiedCheckoutUrl($intention['client_secret']);$paymentTransaction=$paymentTransaction?:PaymentTransaction::where('order_id',$order->id)->where('gateway','paymob')->latest()->first();if(!$paymentTransaction)$paymentTransaction=PaymentTransaction::create(['order_id'=>$order->id,'payment_method_id'=>$order->payment_method_id,'gateway'=>'paymob','status'=>'initiating','original_amount'=>$order->total_amount,'original_currency'=>$order->currency?:$this->paymobSetting('currency','PAYMOB_CURRENCY','EGP'),'idempotency_key'=>'PAYMOB-'.$order->id.'-1']);$paymentTransaction->forceFill(['provider_intention_id'=>$intention['intention_id']??null,'status'=>'pending','provider_status'=>'intention_created','initial_payload'=>SensitiveDataRedactor::redact($intention['request']??[]),'provider_response'=>SensitiveDataRedactor::redact($intention['provider_response']??[]),'metadata'=>array_merge((array)$paymentTransaction->metadata,['payment_url'=>$url])])->save();$order->forceFill(['transaction_id'=>$intention['intention_id']??$order->transaction_id,'status_payment'=>'pending','payment_state'=>'pending'])->save();return ['success'=>true,'payment_url'=>$url,'shorten_url'=>null,'order_number'=>$order->order_number,'client_secret'=>$intention['client_secret'],'intention_id'=>$intention['intention_id']??null,'message'=>'تم إنشاء رابط الدفع بنجاح']; }
 private function createPaymobIntention(Order $order): array { $secret=$this->paymobSetting('secret_key','PAYMOB_SECRET_KEY');$public=$this->paymobSetting('public_key','PAYMOB_PUBLIC_KEY');$integration=$this->paymobSetting('integration_id','PAYMOB_INTEGRATION_ID');if(!$secret||!$public||!$integration)return ['success'=>false,'message'=>'Paymob credentials are not configured.'];$amount=max(1,(int)round(((float)$order->total_amount)*100));$currency=strtoupper((string)($order->currency?:$this->paymobSetting('currency','PAYMOB_CURRENCY','EGP')));[$first,$last]=$this->splitPaymobName((string)($order->customer_name?:'Flashicard Customer'));$items=[];foreach($order->items as $item){$snap=(array)$item->product_snapshot;$items[]=['name'=>mb_substr((string)($snap['name'][app()->getLocale()]??$snap['name']['ar']??$snap['sku']??'Product'),0,255),'amount'=>(int)round((float)$item->price_per_unit*100),'description'=>'Order item','quantity'=>(int)$item->quantity];}$payload=['amount'=>$amount,'currency'=>$currency,'payment_methods'=>[(int)$integration],'items'=>$items?:[['name'=>'Order '.$order->order_number,'amount'=>$amount,'description'=>'Flashicard order','quantity'=>1]],'billing_data'=>['first_name'=>$first,'last_name'=>$last,'email'=>$order->customer_email?:'na@example.com','phone_number'=>$this->normalizePaymobPhone($order->customer_phone),'country'=>'EG','city'=>'Cairo','state'=>'Cairo','postal_code'=>'00000','street'=>'NA','building'=>'NA','floor'=>'NA','apartment'=>'NA'],'customer'=>['first_name'=>$first,'last_name'=>$last,'email'=>$order->customer_email?:'na@example.com','extras'=>['order_number'=>$order->order_number]],'extras'=>['order_id'=>$order->id,'order_number'=>$order->order_number],'special_reference'=>$order->order_number,'notification_url'=>$this->paymobCallbackUrl(),'redirection_url'=>$this->paymobReturnUrl($order),'expiration'=>3600];$response=Http::withHeaders(['Authorization'=>'Token '.$secret])->acceptJson()->asJson()->timeout(20)->post($this->paymobUrl('/v1/intention/'),$payload);if($response->failed())return ['success'=>false,'message'=>'فشل إنشاء نية الدفع في Paymob','http_status'=>$response->status()];$data=$response->json();if(!is_array($data)||empty($data['client_secret']))return ['success'=>false,'message'=>'استجابة Paymob غير مكتملة'];return ['success'=>true,'client_secret'=>$data['client_secret'],'intention_id'=>$data['id']??$data['intention_order_id']??null,'provider_response'=>$data,'request'=>$payload]; }
 private function buildPaymobUnifiedCheckoutUrl(string $clientSecret): string {return $this->paymobUrl('/unifiedcheckout/').'?'.http_build_query(['publicKey'=>$this->paymobSetting('public_key','PAYMOB_PUBLIC_KEY'),'clientSecret'=>$clientSecret]);}
 private function paymobCallbackUrl():string{return (string)($this->paymobSetting('callback_url','PAYMOB_CALLBACK_URL')?:url('/api/v1/paymob/webhook'));} private function paymobReturnUrl(Order $order):string{$b=(string)($this->paymobSetting('return_url','PAYMOB_RETURN_URL')?:url('/payment-status'));return $b.(str_contains($b,'?')?'&':'?').http_build_query(['orderId'=>$order->order_number]);} private function paymobUrl(string $p):string{return rtrim((string)$this->paymobSetting('base_url','PAYMOB_BASE_URL','https://accept.paymob.com'),'/').'/'.ltrim($p,'/');}
 private function splitPaymobName(string $name):array{$p=preg_split('/\s+/',trim($name),2)?:[];return[$p[0]??'Customer',$p[1]??'Flashicard'];} private function normalizePaymobPhone(?string $phone):string{$v=preg_replace('/[^\d+]/','',(string)$phone);return $v!==''?$v:'01000000000';}
 private function paymobSetting(string $key,string $env,mixed $default=null):mixed{$v=config('services.paymob.'.$key);if($v!==null&&$v!=='')return $v;$e=env($env);return $e!==null&&$e!==''?$e:$default;}
}
